<script setup lang="ts">import { onMounted } from 'vue'; import { NAlert, NButton, NSpin } from 'naive-ui'; import StatsCard from '@/components/hermes/competition/dashboard/StatsCard.vue'; import TokenUsageChart from '@/components/hermes/competition/dashboard/TokenUsageChart.vue'; import AgentCoverflowCarousel from '@/components/hermes/competition/dashboard/AgentCoverflowCarousel.vue'; import { useCompetitionDashboardStore } from '@/stores/hermes/competition-dashboard'; const dashboard=useCompetitionDashboardStore(); onMounted(()=>{ void dashboard.loadStats() })</script>
<template><main class="competition-view dashboard-view"><header class="view-header"><div><span class="eyebrow">HICLAW</span><h1>监控仪表盘</h1><p>对比各智能体效率、成本与可靠性</p></div><NButton secondary :loading="dashboard.isLoading" @click="dashboard.loadStats">刷新</NButton></header><AgentCoverflowCarousel /><NAlert v-if="dashboard.error" type="warning" :show-icon="false">{{ dashboard.error }}</NAlert><div v-if="dashboard.isLoading && !dashboard.stats.totalRuns" class="loading"><NSpin size="small" /> 加载中</div><template v-else><section class="stats-grid"><StatsCard label="总运行数" :value="dashboard.stats.totalRuns" /><StatsCard label="成功率" :value="Math.round(dashboard.stats.successRate * 100)" suffix="%" /><StatsCard label="总 Token" :value="Object.values(dashboard.stats.tokens).reduce((a,b)=>a+b,0).toLocaleString()" /><StatsCard label="追踪智能体" :value="Object.keys(dashboard.stats.tokens).length" /></section><TokenUsageChart :values="dashboard.stats.tokens" /></template></main></template>
<style scoped>.competition-view{min-height:100%;display:flex;flex-direction:column;gap:16px;padding:24px;background:var(--bg-page)}.view-header{display:flex;justify-content:space-between;gap:16px}.eyebrow{color:var(--text-primary);font-size:11px;font-weight:700;letter-spacing:.12em}h1{margin:4px 0;font-size:24px;color:var(--text-primary)}p{margin:0;color:var(--text-secondary)}.stats-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px}@media(max-width:720px){.stats-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}.loading{display:flex;gap:8px;align-items:center;color:var(--text-secondary)}</style>
